-- Candidate 49 is the author's Finca (水果莊園) row, not a Juicy Fruits row.
-- Move only the evidence generated by that import session so later Juicy
-- Fruits activity, if any, remains attached to Juicy Fruits.
CREATE TABLE migration_0094_guard (valid INTEGER NOT NULL CHECK (valid = 1));

INSERT INTO migration_0094_guard
SELECT CASE WHEN
  EXISTS (
    SELECT 1 FROM attribute_import_candidates
    WHERE id = 'attribute_candidate:49'
      AND match_status = 'matched'
      AND subject_id = 'attribute_subject_game:game_attribute_import_juicy_fruits'
      AND source_name = '水果莊園'
  )
  AND EXISTS (
    SELECT 1 FROM games
    WHERE id = 'game_attribute_import_juicy_fruits' AND bgg_id = 325698
  )
  AND EXISTS (
    SELECT 1 FROM games
    WHERE id = 'game_bgg_40628' AND bgg_id = 40628
  )
  AND EXISTS (
    SELECT 1 FROM attribute_subjects
    WHERE id = 'attribute_subject_game:game_bgg_40628'
  )
  AND (SELECT COUNT(*) FROM attribute_ratings
       WHERE session_id = 'attribute-import:attribute_candidate:49'
         AND subject_id = 'attribute_subject_game:game_attribute_import_juicy_fruits') = 6
  AND (SELECT COUNT(*) FROM attribute_vote_responses
       WHERE session_id = 'attribute-import:attribute_candidate:49'
         AND subject_a_id = 'attribute_subject_game:game_attribute_import_juicy_fruits') = 6
  AND NOT EXISTS (
    SELECT 1 FROM attribute_ratings
    WHERE session_id = 'attribute-import:attribute_candidate:49'
      AND subject_id = 'attribute_subject_game:game_bgg_40628'
  )
  AND NOT EXISTS (
    SELECT 1 FROM attribute_merge_rebuild_jobs
    WHERE status IN ('pending', 'running')
      AND id <> 'win-history-replay-v1'
  )
THEN 1 ELSE 0 END;

UPDATE games
SET display_name = '神奇果汁',
    english_name = COALESCE(NULLIF(TRIM(english_name), ''), 'Juicy Fruits'),
    normalized_name = '神奇果汁',
    updated_at = CAST((JULIANDAY('now') - 2440587.5) * 86400000 AS INTEGER)
WHERE id = 'game_attribute_import_juicy_fruits' AND bgg_id = 325698;

UPDATE attribute_subjects
SET display_name = '神奇果汁',
    updated_at = CAST((JULIANDAY('now') - 2440587.5) * 86400000 AS INTEGER)
WHERE id = 'attribute_subject_game:game_attribute_import_juicy_fruits';

UPDATE attribute_subject_components
SET label = '神奇果汁'
WHERE subject_id = 'attribute_subject_game:game_attribute_import_juicy_fruits'
  AND component_type = 'base'
  AND game_id = 'game_attribute_import_juicy_fruits';

UPDATE attribute_import_candidates
SET subject_id = 'attribute_subject_game:game_bgg_40628',
    updated_at = CAST((JULIANDAY('now') - 2440587.5) * 86400000 AS INTEGER)
WHERE id = 'attribute_candidate:49';

UPDATE attribute_ratings
SET subject_id = 'attribute_subject_game:game_bgg_40628'
WHERE session_id = 'attribute-import:attribute_candidate:49'
  AND subject_id = 'attribute_subject_game:game_attribute_import_juicy_fruits';

UPDATE attribute_vote_responses
SET subject_a_id = CASE
      WHEN subject_a_id = 'attribute_subject_game:game_attribute_import_juicy_fruits'
      THEN 'attribute_subject_game:game_bgg_40628'
      ELSE subject_a_id
    END,
    subject_b_id = CASE
      WHEN subject_b_id = 'attribute_subject_game:game_attribute_import_juicy_fruits'
      THEN 'attribute_subject_game:game_bgg_40628'
      ELSE subject_b_id
    END
WHERE session_id = 'attribute-import:attribute_candidate:49';

UPDATE attribute_vote_events
SET subject_a_id = CASE
      WHEN subject_a_id = 'attribute_subject_game:game_attribute_import_juicy_fruits'
      THEN 'attribute_subject_game:game_bgg_40628'
      ELSE subject_a_id
    END,
    subject_b_id = CASE
      WHEN subject_b_id = 'attribute_subject_game:game_attribute_import_juicy_fruits'
      THEN 'attribute_subject_game:game_bgg_40628'
      ELSE subject_b_id
    END
WHERE session_id = 'attribute-import:attribute_candidate:49';

-- Replay canonical response history at the next scheduled run.  Using the
-- same source and target subject requests a full rebuild without remapping
-- unrelated Juicy Fruits activity.
UPDATE attribute_merge_rebuild_jobs
SET source_game_id = 'game_bgg_40628',
    target_game_id = 'game_bgg_40628',
    source_subject_id = 'attribute_subject_game:game_bgg_40628',
    target_subject_id = 'attribute_subject_game:game_bgg_40628',
    attribute_id = NULL,
    status = 'pending',
    reset_completed = 0,
    cursor_created_at = -1,
    cursor_stream_id = '',
    cutoff_created_at = CAST((JULIANDAY('now') - 2440587.5) * 86400000 AS INTEGER),
    error_message = NULL,
    updated_at = CAST((JULIANDAY('now') - 2440587.5) * 86400000 AS INTEGER)
WHERE id = 'win-history-replay-v1';

DROP TABLE migration_0094_guard;
